<script lang="ts">
 import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import CreateDatabase from '$lib/components/database/CreateDatabase.svelte';import {databaseState} from '$lib/database/store';import {workspace} from '$lib/stores/workspace';import {engines,usersFor,sizeLabel,host,port,adminTool,type Engine} from '$lib/database/model';
 let query='',filter='All engines',serverEngine:Engine='MySQL',skip=false;
 $: rows=$databaseState.databases.filter(d=>(filter==='All engines'||d.engine===filter)&&[d.name,d.engine,$workspace.projects.find(p=>p.id===d.project)?.name].join(' ').toLowerCase().includes(query.toLowerCase().trim()));
 $: measured=$databaseState.databases.filter(d=>d.bytes!==null);$: total=measured.reduce((n,d)=>n+(d.bytes||0),0);
</script>
<Heading title="Databases" subtitle="Manage databases, access and connection details on this server."/>
<div class="stack db6-stack"><section class="card table-card"><div class="table-head"><div class="section-title"><h3>Databases List</h3><p class="subtitle">All databases, their sizes, user accounts and table counts.</p></div><div class="toolbar"><label class="search"><Icon name="Search"/><input bind:value={query} placeholder="Search databases…" aria-label="Search databases"/></label><select class="input" bind:value={filter} aria-label="Filter database engine"><option>All engines</option>{#each engines as e}<option>{e}</option>{/each}</select><div class="db6-metrics"><span>Database count <strong>{$databaseState.databases.length}</strong></span><span>Total size <strong>{skip?'Skipped':sizeLabel(total)}{!skip&&measured.length<$databaseState.databases.length?' (partial)':''}</strong></span></div></div></div><div class="table-wrap"><table class="db6-list"><thead><tr><th>Database name</th><th>Engine</th><th>Size</th><th>Users</th><th>Tables</th><th>Actions</th></tr></thead><tbody>{#each rows as d (d.id)}<tr><td><div class="row"><span class="icon-box"><Icon name="Databases"/></span><div class="grow"><a class="link-btn mono native-path" href={'/databases/'+d.id}>{d.name}</a><small>{$workspace.projects.find(p=>p.id===d.project)?.name||'Standalone database'} · {usersFor($databaseState,d.id).some(u=>u.hosts.length)?'Remote configured':'Private only'}</small></div></div></td><td data-label="Engine">{d.engine}</td><td data-label="Size">{skip?'—':sizeLabel(d.bytes)}</td><td data-label="Users">{usersFor($databaseState,d.id).length}</td><td data-label="Tables">{d.tables.length}</td><td><a class="btn secondary small" href={'/databases/'+d.id}>Manage <Icon name="Arrow"/></a></td></tr>{:else}<tr><td colspan="6">No matching databases. Create a database below or change your search.</td></tr>{/each}</tbody></table></div><div class="db6-list-footer"><label class="check"><input type="checkbox" bind:checked={skip}/> Skip database size calculation</label></div></section>
<CreateDatabase/>
<section class="card"><div class="row between wrap section-title"><div><h3>Server Details</h3><p class="subtitle">Database software and connection configuration · sample values.</p></div><select class="input db6-engine" bind:value={serverEngine} aria-label="Server details engine">{#each engines as e}<option>{e}</option>{/each}</select></div><div class="summary-list db6-server-facts">{#each [['Version',serverEngine==='PostgreSQL'?'PostgreSQL 16 (example)':serverEngine==='MySQL'?'MySQL 8.0 (example)':'MariaDB 10.11 (example)'],['Hostname',host(serverEngine)+' (example)'],['Port',port(serverEngine)],['Network access','Private by default'],['Administration tool',adminTool(serverEngine)]] as fact}<div><span>{fact[0]}</span><strong>{fact[1]}</strong></div>{/each}</div></section></div>
